-- Story 16.1 (FR67): single_preferences — a single records what matters to
-- her in her own free-text words, and chooses per item whether whoever
-- manages her process can see it.
--
-- Hand-written, not generated by `supabase db diff`. That command cannot run
-- in this repo: supabase/schemas/ declares only 5 of the database's 117
-- functions, so provisioning the declarative shadow database fails as soon as
-- a view, policy or SQL-language function references any of the other 112.
-- This migration mirrors the declarative delta in 01_tables.sql,
-- 04_triggers.sql, 05_policies.sql and 06_grants.sql exactly.
--
-- Purely additive: creates one new table. No column is dropped or rewritten,
-- so no existing row is touched.

create table public.single_preferences (
    id bigint generated by default as identity primary key,
    account_id bigint not null,
    single_id bigint not null,
    body text not null,
    visible_to_manager boolean not null default true,
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now()
);

comment on table public.single_preferences is 'FR63 invariant: these rows MUST NEVER be used to filter, rank, score or match anything. This invariant currently has no mechanical guard; the comment is the only place it is written down next to the data. If you are reading this, do not build a feature that treats these rows as a signal.';

comment on column public.single_preferences.visible_to_manager is 'Default true deliberately — a preference nobody reads is not participation (Story 16.1 AC).';

-- The single_id FK is composite on (account_id, single_id) so a row can never
-- point at a single in another tenant, even if a caller supplies a foreign id.
alter table public.single_preferences
    add constraint single_preferences_account_id_fkey foreign key (account_id) references public.accounts(id) on delete cascade;
alter table public.single_preferences
    add constraint single_preferences_single_id_fkey
    foreign key (account_id, single_id) references public.singles(account_id, id) on delete cascade;

create index single_preferences_account_id_idx on public.single_preferences using btree (account_id);
create index single_preferences_single_id_idx on public.single_preferences using btree (single_id);

alter table public.single_preferences enable row level security;
alter table public.single_preferences force row level security;

-- AD-1: account_id is set by the server on insert, never accepted from the
-- client. Same shape as set_singles_account_id.
create or replace trigger set_single_preferences_account_id
    before insert on public.single_preferences
    for each row execute function public.set_account_id_default();

-- A single owns her preferences with full CRUD; a manager (parent_admin or
-- self_manager) may read only the rows she has explicitly shared. `helper` is
-- deliberately excluded — granting it would be the first table in the schema
-- to do so, which is a product decision, not a schema one.
create policy "Single preferences owned by single" on public.single_preferences
    for all to authenticated
    using (
        account_id = public.current_context_id()
        and exists (
            select 1 from public.singles s
            where s.id = single_preferences.single_id
              and s.account_id = public.current_context_id()
              and s.member_id = public.current_member_id()
        )
    )
    with check (
        account_id = public.current_context_id()
        and exists (
            select 1 from public.singles s
            where s.id = single_preferences.single_id
              and s.account_id = public.current_context_id()
              and s.member_id = public.current_member_id()
        )
    );

create policy "Single preferences readable by manager when shared" on public.single_preferences
    for select to authenticated
    using (
        account_id = public.current_context_id()
        and visible_to_manager = true
        and public.current_member_role() in ('parent_admin', 'self_manager')
    );

revoke all on sequence public.single_preferences_id_seq from anon;
grant all on sequence public.single_preferences_id_seq to authenticated;
grant all on sequence public.single_preferences_id_seq to service_role;

revoke all on table public.single_preferences from anon, authenticated;
grant select, insert, update, delete on table public.single_preferences to authenticated;
grant all on table public.single_preferences to service_role;
